with zipfile.ZipFile(io.BytesIO(raw)) as z:
 manifest=json.loads(z.read('manifest.json'))
 for name,digest in manifest.items():
  assert '/' not in name and '..' not in name,name
  content=z.read(name)
  assert hashlib.sha256(content).hexdigest()==digest,name
  (pathlib.Path(os.environ['REPL_TROT_TEMP'])/name).write_bytes(content)
print('EMBEDDED_SOLVER_AND_VIEWER_HASH_VERIFIED=YES',flush=True)
BOOT_PAYLOAD
export PYTHONPATH="$T" REPL_SCRIPT="$(readlink -f "$0")" REPL_TROT_VIEWER="$T/viewer.html"
python3 "$T/driver.py" "$D"
REVIEW="$D/$CAMPAIGN"
[[ -f "$REVIEW/receipt.json" && -f "$REVIEW/index.html" ]] || { echo 'BLOCKED:FINAL_REVIEW_NOT_COMPLETE';exit 2; }
PORT="$(python3 - "$REVIEW" <<'REUSE_PORT'
import sys,pathlib,urllib.request,hashlib
p=pathlib.Path(sys.argv[1]);index=(p/'index.html').read_bytes();digest=hashlib.sha256(index).hexdigest()
for port in range(8765,8830):
 try:
  with urllib.request.urlopen('http://127.0.0.1:%d/index.html'%port,timeout=.15) as response:b=response.read()
  if hashlib.sha256(b).hexdigest()==digest:print(port);break
 except Exception:pass
REUSE_PORT
)"
if [[ -z "$PORT" ]];then
 PORT="$(python3 - <<'FIND_PORT'
import socket
for port in range(8765,8830):
 with socket.socket() as s:
  try:s.bind(('127.0.0.1',port))
  except OSError:continue
  print(port);break
else:raise SystemExit('BLOCKED:NO_FREE_LOCAL_PORT')
FIND_PORT
)"
 if command -v setsid >/dev/null;then
  setsid python3 -m http.server "$PORT" --bind 127.0.0.1 --directory "$REVIEW" > "$REVIEW/server.log" 2>&1 </dev/null &
 else
  nohup python3 -m http.server "$PORT" --bind 127.0.0.1 --directory "$REVIEW" > "$REVIEW/server.log" 2>&1 </dev/null &
 fi
 printf 'VIEWER_PID=%s\n' "$!"
fi
python3 - "$PORT" "$REVIEW" <<'HTTP_CHECK'
import sys,hashlib,json,time,pathlib,urllib.request
p=pathlib.Path(sys.argv[2]);port=int(sys.argv[1]);r=json.loads((p/'receipt.json').read_text());names=['index.html','Repl_TROT_LONG_STRIDE_v0.6.38.glb']
for tries in range(30):
 try:
  for name in names:
   with urllib.request.urlopen('http://127.0.0.1:%d/%s'%(port,name),timeout=5) as resp:body=resp.read()
   assert hashlib.sha256(body).hexdigest()==r['files'][name],name
  print('VIEWER_AND_FULL_GLB_HTTP_READBACK=PASS',flush=True);break
 except Exception:
  if tries==29:raise
  time.sleep(.3)
HTTP_CHECK
URL="http://127.0.0.1:$PORT/index.html"
echo "REPL_TROT_VIEWER_URL=$URL"
if command -v termux-open-url >/dev/null;then
 termux-open-url "$URL" && echo 'ANDROID_VIEWER_OPEN_REQUESTED=YES' || echo 'ANDROID_VIEWER_OPEN_REQUESTED=FAILED'
else
 echo 'ANDROID_VIEWER_OPEN_REQUESTED=UNAVAILABLE; URL_ABOVE'
fi
printf 'FINAL_STAGE=GENERATED_AND_HTTP_VERIFIED; OWNER_VISUAL_APPROVAL=PENDING\n'
